#!/usr/bin/env rust-script
//! This script generates the `src/icons.rs` file from the `MaterialSymbolsRounded-Regular.codepoints` file.
//! Install the `rust-script` crate with `cargo install rust-script` to run this script.

use std::collections::{BTreeMap, HashSet};
use std::path::PathBuf;

pub fn main() {
    let google_codepoints = include_str!("./MaterialSymbolsRounded-Regular.codepoints");
    let mdi_scss = include_str!("./materialdesignicons.scss");

    let mut icons: BTreeMap<String, String> = BTreeMap::new();
    let mut mdi_icons: BTreeMap<String, String> = BTreeMap::new();

    // 1. Parse Google Material Symbols
    for point in google_codepoints.lines().map(str::trim) {
        let parts: Vec<&str> = point.split(' ').collect();
        if parts.len() > 1 {
            let name = parts[0].to_uppercase();
            let addr = parts[1];
            icons.insert(format!("ICON_{name}"), addr.to_string());
        }
    }

    // 2. Parse Pictogrammers MDI
    for line in mdi_scss.lines().map(str::trim) {
        if line.starts_with('"') && line.contains(':') {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() == 2 {
                let name = parts[0]
                    .trim_matches(|c| c == '"' || c == ' ' || c == '\'')
                    .replace('-', "_")
                    .to_uppercase();
                let addr = parts[1]
                    .trim_matches(|c| c == ' ' || c == ',' || c == ';')
                    .to_lowercase();

                if !name.is_empty() && !addr.is_empty() {
                    // Always add MDI_ prefix
                    mdi_icons.insert(format!("MDI_{name}"), addr.clone());
                    // Also add as ICON_ if not already claimed by Google, or add anyway
                    icons.entry(format!("ICON_{name}")).or_insert(addr);
                }
            }
        }
    }

    let mut code = String::from("//! Generated by gen_codepoints.rs - DO NOT EDIT MANUALLY\n\n");
    code.push_str("// =============================================================================\n");
    code.push_str("// Material Icons & Pictogrammers MDI (Universal ICON_ prefix)\n");
    code.push_str("// =============================================================================\n\n");

    for (name, addr) in &icons {
        code.push_str(&format!(
            "pub const {name}: crate::MaterialIcon = crate::MaterialIcon::new(\"\\u{{{addr}}}\");\n"
        ));
    }

    code.push_str("\n// =============================================================================\n");
    code.push_str("// Pictogrammers MDI Explicit Namespace (MDI_ prefix)\n");
    code.push_str("// =============================================================================\n\n");

    for (name, addr) in &mdi_icons {
        code.push_str(&format!(
            "pub const {name}: crate::MaterialIcon = crate::MaterialIcon::new(\"\\u{{{addr}}}\");\n"
        ));
    }

    let file = PathBuf::from(file!());
    let icons_path = file.parent().unwrap().join("src").join("icons.rs");
    std::fs::write(&icons_path, code).expect("Failed to write src/icons.rs");

    println!(
        "Successfully generated src/icons.rs with {} ICON_ and {} MDI_ constants!",
        icons.len(),
        mdi_icons.len()
    );
}


